// 1. 排除普攻 (关键修正)
if (args.move.type === 'basic') return;

// 2. 计数
let count = actor.getFlag('xjzl-system', 'neigong_qisha_count') || 0;
count++;
await actor.setFlag('xjzl-system', 'neigong_qisha_count', count);

// 3. 每3次触发返还
if (count % 3 === 0) {
    // 计算实际消耗 (基础消耗 - 减耗)
    const baseCost = args.move.currentCost?.mp || 0;
    const reduction = actor.system.combat.costs?.neili?.total || 0;
    const actualCost = Math.max(0, baseCost - reduction);

    if (actualCost > 0) {
        // 执行返还
        await actor.applyHealing({amount: actualCost, type: 'mp', showScrolling: true});
        ui.notifications.info(`七杀经：第 ${count} 次出招，内力已返还。`);
    }
}

if (args.isDead) {
    await args.attacker.applyHealing({amount: 5, type: 'mp'});
    ui.notifications.info('七杀经：击杀回复5点内力');
}

if (args.isCrit) {
    // 1. 造成伤害
    await args.target.applyDamage({ amount: 20, type: 'poison', isHit: true, attacker: args.attacker });

    // 2. 发送全员卡片
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <header class="card-header" style="border-bottom:1px solid #5e4c41; margin-bottom:5px;">
                <h3 style="margin:0;">《六煞经》- 煞气入体</h3>
            </header>
            <div style="margin-left: 5px; font-size: 0.9em; color: #4b4b4b;">
                <p><i class="fas fa-skull-crossbones" style="color:#2e7d32;"></i> 暴击触发！</p>
                <p>额外造成 <span style="color:#2e7d32; font-weight:bold;">20</span> 点毒素伤害。</p>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({ actor: args.attacker })
    });
}

if (args.isCrit) {
    // 1. 造成伤害
    await args.target.applyDamage({ amount: 40, type: 'poison', isHit: true, attacker: args.attacker });

    // 2. 施加易伤
    // 我们传入一个对象，AE管理器会自动将其与系统预设的 yishang 合并
    const effectData = {
        id: "yishang",
        flags: {
            "xjzl-system": { maxStacks: 3 } // 强制限制为 3 层
        }
    };
    await game.xjzl.api.effects.addEffect(args.target, effectData);

    // 3. 发送全员卡片
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <header class="card-header" style="border-bottom:1px solid #5e4c41; margin-bottom:5px;">
                <h3 style="margin:0;">《六煞经》- 六煞齐出</h3>
            </header>
            <div style="margin-left: 5px; font-size: 0.9em; color: #4b4b4b;">
                <p><i class="fas fa-skull-crossbones" style="color:#2e7d32;"></i> 暴击触发！</p>
                <ul style="margin:0; padding-left:20px;">
                    <li>额外造成 <span style="color:#2e7d32; font-weight:bold;">40</span> 点毒素伤害。</li>
                    <li>撕裂伤口，施加 <b>[易伤]</b> (上限3层)。</li>
                </ul>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({ actor: args.attacker })
    });
}

if (args.actionType === 'attack' && args.isHit) {
    const dushu = args.attacker.system.arts.dushu.total || 0;
    const bonus = dushu * 2;
    if (bonus > 0) {
        const dmgRes = await args.target.applyDamage({ amount: bonus, type: 'poison', isHit: true, attacker: args.attacker, ignoreMinDamage: true });

        let losses = [];
        if (dmgRes.hutiLost > 0) losses.push(`${dmgRes.hutiLost}护体`);
        if (dmgRes.hpLost > 0) losses.push(`${dmgRes.hpLost}气血`);
        let lossText = losses.length > 0 ? losses.join(", ") : "被抗性完全抵消";

        const content = `<div class="xjzl-chat-card">
            <div style="padding:5px; padding-left:8px; border-left:4px solid #27ae60; background:rgba(39,174,96,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#1e8449; font-size:1.1em;"><i class="fas fa-spider"></i> 毒邪附伤</div>
                <div style="font-size:0.9em; margin-top:5px; color:#555;">
                    附带 <b>${bonus}</b> 点毒素伤害。<br>
                    <span style="color:#666;">(实际造成: ${lossText})</span>
                </div>
            </div>
        </div>`;

        ChatMessage.create({
            user: game.user.id,
            speaker: ChatMessage.getSpeaker({ actor: args.attacker }),
            content: content
        });
    }
}

if (args.type === 'poison' && args.output.damage > 0) {
    // 进来就翻倍！
    args.output.damage *= 2;
    const finalDmg = args.output.damage;

    const roll = await new Roll('1d20').evaluate();
    if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

    const threshold = 15;
    const isSuccess = roll.total >= threshold;

    let content = `<div class="xjzl-chat-card" style="padding:5px;">
        <div class="card-header" style="border-bottom:1px solid #ccc; margin-bottom:5px;">
            <h3 style="margin:0;">毒邪神煞 - 嗜毒</h3>
        </div>
        <div style="text-align:center; font-size:1.2em; margin:5px 0;">
            🎲 <strong>${roll.total}</strong> <span style="font-size:0.8em; color:#666;">(DC ${threshold})</span>
        </div>`;

    if (isSuccess) {
        await args.target.applyHealing({amount: finalDmg, type: 'hp', showScrolling: true});
        args.output.abort = true; // 免疫伤害
        content += `<div style="color:green; font-weight:bold; text-align:center;"><i class="fas fa-check-circle"></i> 吸收成功</div><div style="margin-top:5px; font-size:0.9em;">毒煞化为生机，吸收 <b>${finalDmg}</b> 点毒素转化为气血。</div>`;
    } else {
        content += `<div style="color:red; font-weight:bold; text-align:center;"><i class="fas fa-skull"></i> 吸收失败</div><div style="margin-top:5px; font-size:0.9em;">毒素攻心！承受翻倍毒伤 <b>${finalDmg}</b> 点。</div>`;
    }
    content += `</div>`;

    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({ actor: args.target }),
        content: content
    });
}

if (args.actionType === 'attack' && args.isHit) {
    const dushu = args.attacker.system.arts.dushu.total || 0;
    const bonus = dushu * 3;
    if (bonus > 0) {
        const dmgRes = await args.target.applyDamage({ amount: bonus, type: 'poison', isHit: true, attacker: args.attacker, ignoreMinDamage: true });

        let losses = [];
        if (dmgRes.hutiLost > 0) losses.push(`${dmgRes.hutiLost}护体`);
        if (dmgRes.hpLost > 0) losses.push(`${dmgRes.hpLost}气血`);
        let lossText = losses.length > 0 ? losses.join(", ") : "被抗性完全抵消";

        const content = `<div class="xjzl-chat-card">
            <div style="padding:5px; padding-left:8px; border-left:4px solid #27ae60; background:rgba(39,174,96,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#1e8449; font-size:1.1em;"><i class="fas fa-spider"></i> 毒邪附伤</div>
                <div style="font-size:0.9em; margin-top:5px; color:#555;">
                    附带 <b>${bonus}</b> 点毒素伤害。<br>
                    <span style="color:#666;">(实际造成: ${lossText})</span>
                </div>
            </div>
        </div>`;

        ChatMessage.create({
            user: game.user.id,
            speaker: ChatMessage.getSpeaker({ actor: args.attacker }),
            content: content
        });
    }
}

if (args.type === 'poison' && args.output.damage > 0) {
    args.output.damage *= 2;
    const finalDmg = args.output.damage;

    const roll = await new Roll('1d20').evaluate();
    if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

    const threshold = 10;
    const isSuccess = roll.total >= threshold;

    let content = `<div class="xjzl-chat-card" style="padding:5px;">
        <div class="card-header" style="border-bottom:1px solid #ccc; margin-bottom:5px;">
            <h3 style="margin:0;">毒邪神煞 - 嗜毒</h3>
        </div>
        <div style="text-align:center; font-size:1.2em; margin:5px 0;">
            🎲 <strong>${roll.total}</strong> <span style="font-size:0.8em; color:#666;">(DC ${threshold})</span>
        </div>`;

    if (isSuccess) {
        await args.target.applyHealing({amount: finalDmg, type: 'hp', showScrolling: true});
        args.output.abort = true;
        content += `<div style="color:green; font-weight:bold; text-align:center;"><i class="fas fa-check-circle"></i> 吸收成功</div><div style="margin-top:5px; font-size:0.9em;">毒煞化为生机，吸收 <b>${finalDmg}</b> 点毒素转化为气血。</div>`;
    } else {
        content += `<div style="color:red; font-weight:bold; text-align:center;"><i class="fas fa-skull"></i> 吸收失败</div><div style="margin-top:5px; font-size:0.9em;">毒素攻心！承受翻倍毒伤 <b>${finalDmg}</b> 点。</div>`;
    }
    content += `</div>`;

    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({ actor: args.target }),
        content: content
    });
}

if (args.actionType === 'attack' && args.isHit) {
    const dushu = args.attacker.system.arts.dushu.total || 0;
    const bonus = dushu * 4;
    if (bonus > 0) {
        const dmgRes = await args.target.applyDamage({ amount: bonus, type: 'poison', isHit: true, attacker: args.attacker, ignoreMinDamage: true });

        let losses = [];
        if (dmgRes.hutiLost > 0) losses.push(`${dmgRes.hutiLost}护体`);
        if (dmgRes.hpLost > 0) losses.push(`${dmgRes.hpLost}气血`);
        let lossText = losses.length > 0 ? losses.join(", ") : "被抗性完全抵消";

        const content = `<div class="xjzl-chat-card">
            <div style="padding:5px; padding-left:8px; border-left:4px solid #27ae60; background:rgba(39,174,96,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#1e8449; font-size:1.1em;"><i class="fas fa-spider"></i> 毒邪附伤</div>
                <div style="font-size:0.9em; margin-top:5px; color:#555;">
                    附带 <b>${bonus}</b> 点毒素伤害。<br>
                    <span style="color:#666;">(实际造成: ${lossText})</span>
                </div>
            </div>
        </div>`;

        ChatMessage.create({
            user: game.user.id,
            speaker: ChatMessage.getSpeaker({ actor: args.attacker }),
            content: content
        });
    }
}

if (args.type === 'poison' && args.output.damage > 0) {
    args.output.damage *= 2;
    const finalDmg = args.output.damage;

    const roll = await new Roll('1d20').evaluate();
    if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

    const threshold = 5;
    const isSuccess = roll.total >= threshold;

    let content = `<div class="xjzl-chat-card" style="padding:5px;">
        <div class="card-header" style="border-bottom:1px solid #ccc; margin-bottom:5px;">
            <h3 style="margin:0;">毒邪神煞 - 嗜毒</h3>
        </div>
        <div style="text-align:center; font-size:1.2em; margin:5px 0;">
            🎲 <strong>${roll.total}</strong> <span style="font-size:0.8em; color:#666;">(DC ${threshold})</span>
        </div>`;

    if (isSuccess) {
        await args.target.applyHealing({amount: finalDmg, type: 'hp', showScrolling: true});
        args.output.abort = true;
        content += `<div style="color:green; font-weight:bold; text-align:center;"><i class="fas fa-check-circle"></i> 吸收成功</div><div style="margin-top:5px; font-size:0.9em;">毒煞化为生机，吸收 <b>${finalDmg}</b> 点毒素转化为气血。</div>`;
    } else {
        content += `<div style="color:red; font-weight:bold; text-align:center;"><i class="fas fa-skull"></i> 吸收失败</div><div style="margin-top:5px; font-size:0.9em;">毒素攻心！承受翻倍毒伤 <b>${finalDmg}</b> 点。</div>`;
    }
    content += `</div>`;

    ChatMessage.create({
        user: game.user.id,
        speaker: ChatMessage.getSpeaker({ actor: args.target }),
        content: content
    });
}

// 0. 过滤普通攻击 (保留趁虚而入)
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

// 1. 读取计数
let count = (actor.getFlag('xjzl-system', 'neigong_wudu_count') || 0) + 1;
let isActive = false;

// 2. 判定触发
if (count >= 3) {
    isActive = true;
    actor.showFloatyText("五毒运转: 3/3", {fill: "#00FF00"});
    count = 0;
} else {
    actor.showFloatyText(`五毒运转: ${count}/3`);
}

// 3. 存储状态供HIT使用
await actor.setFlag('xjzl-system', 'neigong_wudu_count', count);
await actor.setFlag('xjzl-system', 'neigong_wudu_active', isActive);

// 0. 过滤普通攻击
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

// 读取 ATTACK 阶段存入的 Flag
const isActive = actor.getFlag('xjzl-system', 'neigong_wudu_active');

if (isActive) {
    const effTemplate = thisItem.effects.getName("五毒").toObject();
    delete effTemplate._id;
    effTemplate.origin = thisItem.uuid;
    effTemplate.duration = { rounds: 2 };

    await game.xjzl.api.effects.addEffect(args.target, effTemplate);

    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding: 5px 10px;"><div style="color:purple;"><b>${args.attacker.name}</b> 运转五毒真经，掌蕴剧毒！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: args.attacker})
    });
}

// 0. 过滤普通攻击
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

let count = (actor.getFlag('xjzl-system', 'neigong_wudu_count') || 0) + 1;
let isActive = false;

if (count >= 2) {
    isActive = true;
    actor.showFloatyText("五毒运转: 2/2", {fill: "#00FF00"});
    count = 0;
} else {
    actor.showFloatyText(`五毒运转: ${count}/2`);
}

await actor.setFlag('xjzl-system', 'neigong_wudu_count', count);
await actor.setFlag('xjzl-system', 'neigong_wudu_active', isActive);

// 0. 过滤普通攻击
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

const isActive = actor.getFlag('xjzl-system', 'neigong_wudu_active');

// 只有当计数器满足条件，试图施加时，才进行后续判定
if (isActive) {
    const existing = args.target.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'wudu');

    if (existing) {
        // A. 试图施加但已有 -> 引爆
        ChatMessage.create({
            content: `<div class="xjzl-chat-card" style="padding: 5px 10px;"><div style="color:purple;font-weight:bold;font-size:1.1em;"><i class="fas fa-skull-crossbones"></i> 毒素引爆！造成40毒素伤害！</div></div>`,
            speaker: ChatMessage.getSpeaker({actor: args.attacker})
        });

        await args.target.applyDamage({
            amount: 40,
            type: 'poison',
            attacker: args.attacker,
            isHit: true
        });

        await existing.delete();
        actor.showFloatyText("五毒引爆!", {fill: "#800080", fontSize: 40});
    } else {
        // B. 试图施加且没有 -> 施加 (3回合)
        const effTemplate = thisItem.effects.getName("五毒").toObject();
        delete effTemplate._id;
        effTemplate.origin = thisItem.uuid;
        effTemplate.duration = { rounds: 3 };

        await game.xjzl.api.effects.addEffect(args.target, effTemplate);

        ChatMessage.create({
            content: `<div class="xjzl-chat-card" style="padding: 5px 10px;"><div style="color:purple;">毒气入体，<b>${args.target.name}</b> 中毒了！</div></div>`,
            speaker: ChatMessage.getSpeaker({actor: args.attacker})
        });
    }
}

// 0. 过滤普通攻击
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

// Stage 3: 无条件触发
const existing = args.target.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'wudu');

if (existing) {
    // A. 引爆逻辑 (50点)
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding: 5px 10px;"><div style="color:purple;font-weight:bold;font-size:1.2em;"><i class="fas fa-biohazard"></i> 毒素引爆！造成50毒素伤害！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: args.attacker})
    });

    await args.target.applyDamage({
        amount: 50,
        type: 'poison',
        attacker: args.attacker,
        isHit: true
    });
    await existing.delete();
    actor.showFloatyText("五毒引爆!", {fill: "#800080", fontSize: 48});
} else {
    // B. 施加逻辑 (3回合)
    const effTemplate = thisItem.effects.getName("五毒").toObject();
    delete effTemplate._id;
    effTemplate.origin = thisItem.uuid;
    effTemplate.duration = { rounds: 3 };

    await game.xjzl.api.effects.addEffect(args.target, effTemplate);

    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding: 5px 10px;"><div style="color:purple;">毒气入体，<b>${args.target.name}</b> 中毒了！</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: args.attacker})
    });
}
